const listLatestIngressUsageReports = `-- name: ListLatestIngressUsageReports :many
WITH requested AS (
    SELECT DISTINCT unnest($3::text[]) AS public_url_id,
                    unnest($4::bigint[]) AS publish_run_number,
                    unnest($5::timestamptz[]) AS bucket_start
)
SELECT reports.public_url_id, reports.publish_run_number, reports.bucket_start, reports.bucket_end,
       reports.observed_through, reports.report_revision, reports.connection_attempts,
       reports.policy_denials, reports.capacity_denials, reports.visitor_stream_open_failures,
       reports.successful_streams, reports.connection_nanoseconds, reports.ingress_bytes,
       reports.egress_bytes, reports.final
FROM requested
CROSS JOIN LATERAL (
    SELECT history.id, history.ingress_id, history.ingress_run_id, history.public_url_id, history.publish_run_number, history.bucket_start, history.bucket_end, history.observed_through, history.report_revision, history.connection_attempts, history.policy_denials, history.capacity_denials, history.visitor_stream_open_failures, history.successful_streams, history.connection_nanoseconds, history.ingress_bytes, history.egress_bytes, history.histogram_data, history.final, history.received_at FROM control.ingress_usage_reports AS history
    WHERE history.ingress_id = $1
      AND history.ingress_run_id = $2
      AND history.public_url_id = requested.public_url_id
      AND history.publish_run_number = requested.publish_run_number
      AND history.bucket_start = requested.bucket_start
    ORDER BY history.report_revision DESC
    LIMIT 1
) AS reports
`

type ListLatestIngressUsageReportsParams struct {
	IngressID         string
	IngressRunID      string
	PublicUrlIds      []string
	PublishRunNumbers []int64
	BucketStarts      []pgtype.Timestamptz
}

type ListLatestIngressUsageReportsRow struct {
	PublicURLID               string
	PublishRunNumber          int64
	BucketStart               pgtype.Timestamptz
	BucketEnd                 pgtype.Timestamptz
	ObservedThrough           pgtype.Timestamptz
	ReportRevision            int64
	ConnectionAttempts        int64
	PolicyDenials             int64
	CapacityDenials           int64
	VisitorStreamOpenFailures int64
	SuccessfulStreams         int64
	ConnectionNanoseconds     int64
	IngressBytes              int64
	EgressBytes               int64
	Final                     bool
}

// ingress and usage-run guards serialize this source's append-only history.
// fetch bounded metadata; exact replays load histogram payloads separately.
func (q *Queries) ListLatestIngressUsageReports(ctx context.Context, arg ListLatestIngressUsageReportsParams) ([]ListLatestIngressUsageReportsRow, error) {
	rows, err := q.db.Query(ctx, listLatestIngressUsageReports,
		arg.IngressID,
		arg.IngressRunID,
		arg.PublicUrlIds,
		arg.PublishRunNumbers,
		arg.BucketStarts,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListLatestIngressUsageReportsRow
	for rows.Next() {
		var i ListLatestIngressUsageReportsRow
		if err := rows.Scan(
			&i.PublicURLID,
			&i.PublishRunNumber,
			&i.BucketStart,
			&i.BucketEnd,
			&i.ObservedThrough,
			&i.ReportRevision,
			&i.ConnectionAttempts,
			&i.PolicyDenials,
			&i.CapacityDenials,
			&i.VisitorStreamOpenFailures,
			&i.SuccessfulStreams,
			&i.ConnectionNanoseconds,
			&i.IngressBytes,
			&i.EgressBytes,
			&i.Final,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

